<?php $layout = kimpu_homepage_section_value( 'about', 'layout', 'image-left' ); $page = kimpu_homepage_source_page( 'kimpu_about_source_page' ); if ( ! $page && 'page' === get_option( 'show_on_front' ) ) { $page = get_post( get_option( 'page_on_front' ) ); } $image_id = absint( get_theme_mod( 'kimpu_about_image', 0 ) ); ?>
<section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'about' ) ); ?> about-layout-<?php echo esc_attr( $layout ); ?>" id="about-theme"><div class="container"><div class="about-grid"><?php if ( $image_id && 'centered' !== $layout ) : ?><div class="about-media"><?php echo wp_get_attachment_image( $image_id, 'large', false, array( 'alt' => esc_attr( get_theme_mod( 'kimpu_about_image_alt', '' ) ) ) ); ?></div><?php endif; ?><div class="about-copy"><?php kimpu_homepage_section_header( 'about' ); ?><?php if ( $page ) : ?><div class="entry-content"><?php echo apply_filters( 'the_content', $page->post_content ); ?></div><?php elseif ( ! kimpu_homepage_section_value( 'about', 'description', '' ) ) : ?><p class="empty-state"><?php esc_html_e( 'Select an About page in the Homepage Builder to add your introduction.', 'kimpu-multipurpose' ); ?></p><?php endif; ?><?php if ( get_theme_mod( 'kimpu_about_experience', '' ) ) : ?><p class="experience-indicator"><strong><?php echo esc_html( get_theme_mod( 'kimpu_about_experience' ) ); ?></strong> <?php esc_html_e( 'of experience', 'kimpu-multipurpose' ); ?></p><?php endif; ?><?php if ( get_theme_mod( 'kimpu_about_cta_text', '' ) && get_theme_mod( 'kimpu_about_cta_url', '' ) ) : ?><a class="button" href="<?php echo esc_url( get_theme_mod( 'kimpu_about_cta_url' ) ); ?>"><?php echo esc_html( get_theme_mod( 'kimpu_about_cta_text' ) ); ?></a><?php endif; ?></div></div></div></section>
